(function (window, document) {
    'use strict';

    if (window.QmxUmlSequenceEditor?.version) return;
    const Diagram = window.QmxDiagram;
    if (!Diagram) { console.error('[QMX Sequence] Diagram renderer must load first.'); return; }

    const TOOL_DEFS = [
        ['select', 'Select', 'নির্বাচন'],
        ['actor', 'Actor lifeline', 'অ্যাক্টর লাইফলাইন'],
        ['object', 'Object lifeline', 'অবজেক্ট লাইফলাইন'],
        ['boundary', 'Boundary', 'বাউন্ডারি'],
        ['control', 'Control', 'কন্ট্রোল'],
        ['entity', 'Entity', 'এনটিটি'],
        ['database', 'Database', 'ডেটাবেস'],
        ['message', 'Smart message', 'স্মার্ট মেসেজ'],
        ['return-message', 'Return message', 'রিটার্ন মেসেজ'],
        ['self-message', 'Self message', 'সেলফ মেসেজ'],
        ['activation', 'Activation', 'অ্যাক্টিভেশন'],
        ['fragment', 'Combined fragment', 'কম্বাইন্ড ফ্র্যাগমেন্ট'],
        ['note', 'Note', 'নোট'],
        ['text', 'Annotation', 'টীকা']
    ];
    const LIFELINE_TYPES = new Set(['actor','object','boundary','control','entity','database']);
    const state = { root:null, canvas:null, svg:null, context:null, document:null, selectedId:null, activeTool:'select', interaction:null, connectionStart:null, history:[], historyIndex:-1, controls:{} };

    function uid(prefix='seq') { return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`; }
    function esc(value) { return String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]); }
    function clone(value) { return JSON.parse(JSON.stringify(value)); }
    function snap(value) { const step=Number(state.document?.gridSize||20); return state.document?.snap ? Math.round(value/step)*step : value; }
    function selectedObject() { return state.document?.objects.find((object)=>object.id===state.selectedId)||null; }
    function lifelines() { return state.document?.objects.filter((object)=>object.type==='seq-lifeline')||[]; }
    function nextMessageY() { const ys=(state.document?.objects||[]).filter((o)=>o.type==='seq-message').map((o)=>Number(o.y||0)); return snap(Math.max(170, ys.length?Math.max(...ys)+70:190)); }

    function createDocument() {
        return { version:27, id:uid('uml-sequence'), mode:'uml-sequence', title:'UML Sequence / Interaction Diagram', width:1180, height:760, background:'#ffffff', gridSize:20, sequenceShowGrid:true, sequenceShowNumbers:true, sequenceShowActivations:true, sequenceShowFootbox:false, snap:true, objects:[] };
    }
    function makeLifeline(roleType='object', overrides={}) {
        const names={actor:'User',object:'Object',boundary:'UI',control:'Controller',entity:'Entity',database:'Database'};
        const classes={actor:'Actor',object:'Class',boundary:'Boundary',control:'Control',entity:'Entity',database:'DB'};
        const colors={actor:['#f8fafc','#334155'],object:['#eff6ff','#1d4ed8'],boundary:['#ecfeff','#0e7490'],control:['#f3e8ff','#7e22ce'],entity:['#ecfdf5','#047857'],database:['#fff7ed','#c2410c']};
        return { id:uid('seq-lifeline'), type:'seq-lifeline', roleType, x:260, y:80, width:150, height:64, bottom:700, name:names[roleType]||'Object', className:classes[roleType]||'Class', fill:colors[roleType]?.[0]||'#eff6ff', stroke:colors[roleType]?.[1]||'#1d4ed8', textColor:'#0f172a', lineWidth:2.2, ...overrides };
    }
    function makeMessage(sourceId='', targetId='', messageType='sync', overrides={}) {
        return { id:uid('seq-message'), type:'seq-message', sourceId, targetId, y:nextMessageY(), messageType, label:messageType==='return'?'result':'request()', number:'', stroke:'#0f172a', textColor:'#0f172a', lineWidth:2.2, ...overrides };
    }
    function makeActivation(lifelineId='', overrides={}) { return { id:uid('seq-activation'), type:'seq-activation', lifelineId, y:210, height:130, width:16, fill:'#dbeafe', stroke:'#2563eb', lineWidth:1.8, ...overrides }; }
    function makeFragment(overrides={}) { return { id:uid('seq-fragment'), type:'seq-fragment', x:130, y:180, width:900, height:330, operator:'alt', guard:'[condition]', clauses:['[success]','[failure]'], fill:'#ffffff', stroke:'#475569', textColor:'#0f172a', lineWidth:2, ...overrides }; }
    function makeNote(overrides={}) { return { id:uid('seq-note'), type:'seq-note', x:800, y:150, width:230, height:105, text:'Interaction note', fill:'#fef9c3', stroke:'#ca8a04', textColor:'#713f12', lineWidth:2, ...overrides }; }
    function defaultObject(type) {
        if (LIFELINE_TYPES.has(type)) return makeLifeline(type);
        if (type==='activation') { const line=lifelines()[0]; return makeActivation(line?.id||''); }
        if (type==='fragment') return makeFragment();
        if (type==='note') return makeNote();
        return { id:uid('text'), type:'text', x:80, y:80, text:'Sequence diagram', color:'#0f172a', fontSize:20, fontWeight:'bold' };
    }
    function addMessage(source, target, messageType='sync', overrides={}) {
        const object=makeMessage(source.id,target.id,messageType,overrides);
        if (messageType==='self') object.targetId=source.id;
        state.document.objects.push(object); state.selectedId=object.id; state.connectionStart=null; pushHistory(); render(); setStatus('Smart sequence message created.');
    }
    function connectLifeline(objectId) {
        const object=state.document.objects.find((item)=>item.id===objectId&&item.type==='seq-lifeline'); if(!object)return;
        const messageType=state.activeTool==='return-message'?'return':state.activeTool==='self-message'?'self':'sync';
        if(messageType==='self'){addMessage(object,object,'self',{label:'selfCall()'});state.activeTool='select';updateToolButtons();return;}
        if(!state.connectionStart){state.connectionStart={objectId};setStatus('Source lifeline selected. Choose a target lifeline.');render();return;}
        const source=state.document.objects.find((item)=>item.id===state.connectionStart.objectId&&item.type==='seq-lifeline');if(!source){state.connectionStart=null;render();return;}
        addMessage(source,object,messageType);state.activeTool='select';updateToolButtons();
    }
    function addObject(type){const object=defaultObject(type);const count=lifelines().length;if(object.type==='seq-lifeline'){object.x=snap(150+count*210);object.bottom=state.document.height-55;}else if('x'in object){object.x=snap(Number(object.x)+(state.document.objects.length%4)*24);object.y=snap(Number(object.y)+(state.document.objects.length%3)*20);}state.document.objects.push(object);state.selectedId=object.id;pushHistory();render();setStatus(`${type} added.`);}

    function pushHistory(){if(!state.document)return;const snapshot=JSON.stringify(state.document);if(state.history[state.historyIndex]===snapshot)return;state.history=state.history.slice(0,state.historyIndex+1);state.history.push(snapshot);if(state.history.length>100)state.history.shift();state.historyIndex=state.history.length-1;updateHistoryButtons();}
    function restoreHistory(index){if(index<0||index>=state.history.length)return;state.historyIndex=index;state.document=Diagram.normalizeSpec(JSON.parse(state.history[index]));state.selectedId=null;state.connectionStart=null;state.interaction=null;syncDocumentControls();render();updateHistoryButtons();}
    function undo(){restoreHistory(state.historyIndex-1);} function redo(){restoreHistory(state.historyIndex+1);}
    function updateHistoryButtons(){if(!state.controls.undo)return;state.controls.undo.disabled=state.historyIndex<=0;state.controls.redo.disabled=state.historyIndex>=state.history.length-1;}
    function updateToolButtons(){state.controls.tools?.querySelectorAll('[data-tool]').forEach((button)=>button.classList.toggle('active',button.dataset.tool===state.activeTool));}
    function setTool(tool){state.activeTool=tool;state.connectionStart=null;updateToolButtons();if(['message','return-message','self-message'].includes(tool)){setStatus('Click a source lifeline, then a target lifeline.');render();return;}if(tool!=='select'){addObject(tool);state.activeTool='select';updateToolButtons();}else render();}

    function lifelineHeadBounds(object){return{left:object.x-object.width/2,top:object.y-object.height/2,width:object.width,height:object.height};}
    function objectBounds(object){if(object.type==='seq-lifeline')return lifelineHeadBounds(object);if(object.type==='seq-fragment'||object.type==='seq-note')return{left:object.x,top:object.y,width:object.width,height:object.height};if(object.type==='seq-activation'){const line=state.document.objects.find((o)=>o.id===object.lifelineId);return{left:Number(line?.x||0)-object.width/2,top:object.y,width:object.width,height:object.height};}return{left:Number(object.x||0)-10,top:Number(object.y||0)-10,width:20,height:20};}
    function selectionMarkup(){if(!state.document)return'';const selected=selectedObject();let markup='<g data-sequence-editor-overlay="1">';if(selected){const b=objectBounds(selected);markup+=`<rect x="${b.left-7}" y="${b.top-7}" width="${b.width+14}" height="${b.height+14}" rx="7" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="7 5"/>`;}
        if(['message','return-message','self-message'].includes(state.activeTool)){const y=nextMessageY();lifelines().forEach((object)=>{const started=state.connectionStart?.objectId===object.id;markup+=`<circle data-seq-port-object="${esc(object.id)}" cx="${object.x}" cy="${y}" r="${started?9:7}" fill="${started?'#16a34a':'#2563eb'}" stroke="#fff" stroke-width="2" style="cursor:crosshair"/>`;});}
        return markup+'</g>';}
    function render(){if(!state.canvas||!state.document)return;state.document=Diagram.normalizeSpec(state.document);let svg=Diagram.svgMarkup(state.document);svg=svg.replace('</svg>',`${selectionMarkup()}</svg>`);state.canvas.innerHTML=svg;state.svg=state.canvas.querySelector('svg');syncSelectedControls();updateSummary();}

    function field(label,key,value,type='text',attrs=''){return`<div class="qmx-seq-field"><label>${esc(label)}</label><input type="${type}" data-object="${esc(key)}" value="${esc(value)}" ${attrs}></div>`;}
    function selectField(label,key,value,options){return`<div class="qmx-seq-field"><label>${esc(label)}</label><select data-object="${esc(key)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
    function textareaField(label,key,value){return`<div class="qmx-seq-field"><label>${esc(label)}</label><textarea data-object="${esc(key)}">${esc(value)}</textarea></div>`;}
    function colorField(label,key,value){return field(label,key,value,'color');}
    function syncSelectedControls(){const holder=state.controls.selected;if(!holder)return;const object=selectedObject();if(!object){holder.innerHTML='<div class="qmx-seq-empty">Select a lifeline, message, activation, fragment or note.</div>';return;}let html=`<div class="qmx-seq-type">${esc(object.type)}</div>`;
        if(object.type==='seq-lifeline'){html+=field('Name','name',object.name)+field('Class / role','className',object.className)+selectField('Lifeline type','roleType',object.roleType,[['actor','Actor'],['object','Object'],['boundary','Boundary'],['control','Control'],['entity','Entity'],['database','Database']])+`<div class="qmx-seq-grid2">${field('X','x',object.x,'number')}${field('Head Y','y',object.y,'number')}${field('Width','width',object.width,'number')}${field('Bottom','bottom',object.bottom,'number')}</div>`+`<div class="qmx-seq-grid2">${colorField('Fill','fill',object.fill)}${colorField('Stroke','stroke',object.stroke)}</div>`;}
        else if(object.type==='seq-message'){html+=field('Message','label',object.label)+selectField('Message type','messageType',object.messageType,[['sync','Synchronous'],['async','Asynchronous'],['return','Return'],['create','Create'],['destroy','Destroy'],['self','Self call']])+`<div class="qmx-seq-grid2">${field('Sequence no.','number',object.number)}${field('Y','y',object.y,'number')}</div>`+colorField('Stroke','stroke',object.stroke);}
        else if(object.type==='seq-activation'){html+=selectField('Lifeline','lifelineId',object.lifelineId,lifelines().map((line)=>[line.id,line.name]))+`<div class="qmx-seq-grid2">${field('Y','y',object.y,'number')}${field('Height','height',object.height,'number')}${field('Width','width',object.width,'number')}${colorField('Fill','fill',object.fill)}</div>`;}
        else if(object.type==='seq-fragment'){html+=selectField('Operator','operator',object.operator,[['alt','alt'],['opt','opt'],['loop','loop'],['par','par'],['critical','critical'],['ref','ref']])+field('Guard / title','guard',object.guard)+textareaField('Clauses — one guard per line','clausesText',(object.clauses||[]).join('\n'))+`<div class="qmx-seq-grid2">${field('X','x',object.x,'number')}${field('Y','y',object.y,'number')}${field('Width','width',object.width,'number')}${field('Height','height',object.height,'number')}</div>`;}
        else if(object.type==='seq-note'){html+=textareaField('Text','text',object.text)+`<div class="qmx-seq-grid2">${field('X','x',object.x,'number')}${field('Y','y',object.y,'number')}${field('Width','width',object.width,'number')}${field('Height','height',object.height,'number')}</div>`;}
        else {html+=textareaField('Text','text',object.text)+`<div class="qmx-seq-grid2">${field('X','x',object.x,'number')}${field('Y','y',object.y,'number')}${field('Font size','fontSize',object.fontSize,'number')}${colorField('Color','color',object.color)}</div>`;}
        holder.innerHTML=html;}
    function updateSummary(){const counts={};(state.document?.objects||[]).forEach((o)=>counts[o.type]=(counts[o.type]||0)+1);state.controls.summary.textContent=`${state.document?.objects.length||0} object(s) · ${Object.entries(counts).map(([k,v])=>`${v} ${k.replace('seq-','')}`).join(' · ')}`;}
    function syncDocumentControls(){if(!state.root||!state.document)return;state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;input.type==='checkbox'?input.checked=Boolean(state.document[key]):input.value=state.document[key]??'';});}
    function onRootInput(event){const docKey=event.target.dataset.doc;if(docKey){let value=event.target.type==='checkbox'?event.target.checked:event.target.value;if(event.target.type==='number')value=Number(value);state.document[docKey]=value;render();return;}const key=event.target.dataset.object;if(!key)return;const object=selectedObject();if(!object)return;let value=event.target.type==='checkbox'?event.target.checked:event.target.value;if(event.target.type==='number')value=Number(value);if(key==='clausesText')object.clauses=String(value).split(/\r?\n/).filter(Boolean);else object[key]=value;render();}
    function svgPoint(event){const point=state.svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(state.svg.getScreenCTM().inverse());}
    function onCanvasPointerDown(event){const port=event.target.closest?.('[data-seq-port-object]');if(port){connectLifeline(port.dataset.seqPortObject);event.preventDefault();return;}const target=event.target.closest?.('[data-qmx-object]');if(!target){state.selectedId=null;render();return;}const object=state.document.objects.find((item)=>item.id===target.dataset.qmxObject);if(!object)return;state.selectedId=object.id;if(['message','return-message','self-message'].includes(state.activeTool)&&object.type==='seq-lifeline'){connectLifeline(object.id);event.preventDefault();return;}const point=svgPoint(event);state.interaction={id:object.id,startX:point.x,startY:point.y,origX:Number(object.x||0),origY:Number(object.y||0)};event.target.setPointerCapture?.(event.pointerId);render();}
    function onPointerMove(event){if(!state.interaction||!state.svg)return;const object=state.document.objects.find((item)=>item.id===state.interaction.id);if(!object)return;const point=svgPoint(event);const dx=point.x-state.interaction.startX,dy=point.y-state.interaction.startY;if(object.type==='seq-lifeline')object.x=snap(state.interaction.origX+dx);else if(object.type==='seq-message'||object.type==='seq-activation')object.y=snap(state.interaction.origY+dy);else{object.x=snap(state.interaction.origX+dx);object.y=snap(state.interaction.origY+dy);}render();setStatus('Object moved; attached sequence elements updated automatically.');}
    function onPointerUp(){if(!state.interaction)return;state.interaction=null;pushHistory();render();}
    function deleteSelected(){const id=state.selectedId;if(!id)return;const object=selectedObject();state.document.objects=state.document.objects.filter((item)=>item.id!==id&&!(object?.type==='seq-lifeline'&&((item.type==='seq-message'&&(item.sourceId===id||item.targetId===id))||(item.type==='seq-activation'&&item.lifelineId===id))));state.selectedId=null;pushHistory();render();setStatus('Selected object deleted.');}
    function duplicateSelected(){const object=selectedObject();if(!object)return;const copy=clone(object);copy.id=uid(object.type);if('x'in copy)copy.x=Number(copy.x||0)+30;if('y'in copy)copy.y=Number(copy.y||0)+30;if(copy.type==='seq-message'){copy.y=Number(copy.y||0)+50;}state.document.objects.push(copy);state.selectedId=copy.id;pushHistory();render();setStatus('Selected object duplicated.');}
    function newDocument(){state.document=createDocument();state.selectedId=null;state.connectionStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();render();setStatus('New sequence diagram created.');}

    function presetLogin(){const user=makeLifeline('actor',{x:130,name:'User'}),ui=makeLifeline('boundary',{x:360,name:'Login UI'}),auth=makeLifeline('control',{x:620,name:'Auth Service'}),db=makeLifeline('database',{x:900,name:'User DB'});state.document.objects=[user,ui,auth,db,makeMessage(user.id,ui.id,'sync',{y:190,label:'submitCredentials()'}),makeActivation(ui.id,{y:184,height:90}),makeMessage(ui.id,auth.id,'sync',{y:260,label:'authenticate()'}),makeActivation(auth.id,{y:254,height:200}),makeMessage(auth.id,db.id,'sync',{y:330,label:'findUser()'}),makeActivation(db.id,{y:324,height:70}),makeMessage(db.id,auth.id,'return',{y:400,label:'user'}),makeMessage(auth.id,ui.id,'return',{y:470,label:'token'}),makeMessage(ui.id,user.id,'return',{y:540,label:'dashboard'})];}
    function presetApi(){const client=makeLifeline('actor',{x:130,name:'Client'}),gateway=makeLifeline('boundary',{x:360,name:'API Gateway'}),service=makeLifeline('control',{x:620,name:'Order Service'}),db=makeLifeline('database',{x:900,name:'Orders DB'});state.document.objects=[client,gateway,service,db,makeMessage(client.id,gateway.id,'sync',{y:190,label:'POST /orders'}),makeMessage(gateway.id,service.id,'sync',{y:270,label:'createOrder(dto)'}),makeMessage(service.id,db.id,'sync',{y:350,label:'INSERT order'}),makeMessage(db.id,service.id,'return',{y:430,label:'orderId'}),makeMessage(service.id,gateway.id,'return',{y:510,label:'Order'}),makeMessage(gateway.id,client.id,'return',{y:590,label:'201 Created'})];}
    function presetCheckout(){const c=makeLifeline('actor',{x:100,name:'Customer'}),web=makeLifeline('boundary',{x:290,name:'Web App'}),order=makeLifeline('control',{x:500,name:'Order Service'}),payment=makeLifeline('control',{x:720,name:'Payment'}),inventory=makeLifeline('entity',{x:940,name:'Inventory'});state.document.objects=[c,web,order,payment,inventory,makeMessage(c.id,web.id,'sync',{y:170,label:'checkout()'}),makeMessage(web.id,order.id,'sync',{y:240,label:'placeOrder()'}),makeMessage(order.id,inventory.id,'sync',{y:310,label:'reserveItems()'}),makeMessage(inventory.id,order.id,'return',{y:380,label:'reserved'}),makeMessage(order.id,payment.id,'sync',{y:450,label:'charge()'}),makeMessage(payment.id,order.id,'return',{y:520,label:'paid'}),makeMessage(order.id,web.id,'return',{y:590,label:'confirmation'})];}
    function presetAsync(){const client=makeLifeline('actor',{x:130,name:'Client'}),api=makeLifeline('boundary',{x:360,name:'API'}),queue=makeLifeline('entity',{x:620,name:'Queue'}),worker=makeLifeline('control',{x:900,name:'Worker'});state.document.objects=[client,api,queue,worker,makeMessage(client.id,api.id,'sync',{y:190,label:'startJob()'}),makeMessage(api.id,queue.id,'async',{y:280,label:'publish(job)'}),makeMessage(api.id,client.id,'return',{y:360,label:'202 Accepted'}),makeMessage(queue.id,worker.id,'async',{y:450,label:'consume(job)'}),makeActivation(worker.id,{y:445,height:130}),makeMessage(worker.id,client.id,'async',{y:590,label:'notifyCompleted()'})];}
    function presetAlt(){presetLogin();state.document.objects.push(makeFragment({x:90,y:230,width:980,height:340,operator:'alt',guard:'authentication result',clauses:['[valid credentials]','[invalid credentials]']}));}
    function presetObserver(){const subject=makeLifeline('object',{x:210,name:'Subject'}),o1=makeLifeline('object',{x:520,name:'Observer A'}),o2=makeLifeline('object',{x:830,name:'Observer B'});state.document.objects=[subject,o1,o2,makeMessage(subject.id,subject.id,'self',{y:180,label:'setState()'}),makeMessage(subject.id,o1.id,'async',{y:290,label:'update(state)'}),makeMessage(subject.id,o2.id,'async',{y:390,label:'update(state)'})];}
    function presetTransaction(){const app=makeLifeline('control',{x:260,name:'Application'}),db=makeLifeline('database',{x:760,name:'Database'});state.document.objects=[app,db,makeMessage(app.id,db.id,'sync',{y:190,label:'BEGIN'}),makeActivation(db.id,{y:185,height:330}),makeMessage(app.id,db.id,'sync',{y:280,label:'UPDATE account'}),makeMessage(app.id,db.id,'sync',{y:370,label:'INSERT ledger'}),makeMessage(app.id,db.id,'sync',{y:460,label:'COMMIT'}),makeMessage(db.id,app.id,'return',{y:550,label:'success'})];}
    function applyPreset(name){state.document=createDocument();if(name==='login')presetLogin();else if(name==='api')presetApi();else if(name==='checkout')presetCheckout();else if(name==='async')presetAsync();else if(name==='alt')presetAlt();else if(name==='observer')presetObserver();else if(name==='transaction')presetTransaction();else state.document.objects=[];state.selectedId=null;state.connectionStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();render();setStatus(`${name} preset inserted.`);}

    function onRootClick(event){const tool=event.target.closest?.('[data-tool]')?.dataset.tool;if(tool){setTool(tool);return;}const preset=event.target.closest?.('[data-preset]')?.dataset.preset;if(preset){applyPreset(preset);return;}const act=event.target.closest?.('[data-act]')?.dataset.act;if(!act)return;({new:newDocument,undo,redo,duplicate:duplicateSelected,delete:deleteSelected,close,insert:insertIntoQuestion,'export-svg':exportSvg,'export-png':exportPng}[act]||(()=>{}))();}
    function makeToken(){return`[[qmx-diagram:${Diagram.encodeSpec(state.document)}]]`;}
    function insertIntoQuestion(){const textarea=state.context?.textarea||window.QmxDiagramLauncher?.getActiveTextarea?.();if(!textarea){setStatus('No active question textarea found.');return;}const token=makeToken();if(state.context?.replaceRange){const{start,end}=state.context.replaceRange;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}else{const start=textarea.selectionStart??textarea.value.length;const end=textarea.selectionEnd??start;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.dispatchEvent(new Event('change',{bubbles:true}));setStatus('Sequence diagram inserted into the question.');close();}
    function safeFilename(value){return String(value||'uml-sequence').replace(/[^a-z0-9._-]+/gi,'-').replace(/^-+|-+$/g,'')||'uml-sequence';}
    function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    function exportSvg(){downloadBlob(new Blob([Diagram.svgMarkup(state.document)],{type:'image/svg+xml;charset=utf-8'}),`${safeFilename(state.document.title)}.svg`);setStatus('SVG exported.');}
    function exportPng(){const svg=Diagram.svgMarkup(state.document);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=state.document.width;canvas.height=state.document.height;canvas.getContext('2d').drawImage(image,0,0);URL.revokeObjectURL(url);canvas.toBlob((blob)=>blob&&downloadBlob(blob,`${safeFilename(state.document.title)}.png`),'image/png');setStatus('PNG exported.');};image.onerror=()=>{URL.revokeObjectURL(url);setStatus('PNG export failed.');};image.src=url;}

    function addStyles(){if(document.getElementById('qmx-sequence-styles'))return;const style=document.createElement('style');style.id='qmx-sequence-styles';style.textContent=`.qmx-seq-editor{position:fixed;inset:0;z-index:10080;background:rgba(15,23,42,.72);padding:12px;box-sizing:border-box;font-family:Arial,"Noto Sans Bengali","Segoe UI",sans-serif!important}.qmx-seq-editor button,.qmx-seq-editor input,.qmx-seq-editor select,.qmx-seq-editor textarea{font-family:Arial,"Noto Sans Bengali","Segoe UI",sans-serif!important}.qmx-seq-canvas svg,.qmx-seq-canvas svg text{font-family:Arial,"Noto Sans Bengali","Segoe UI",sans-serif!important}.qmx-seq-shell{width:min(1500px,100%);height:min(940px,100%);margin:auto;background:#f8fafc;border-radius:18px;box-shadow:0 28px 80px rgba(15,23,42,.35);display:grid;grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden}.qmx-seq-header,.qmx-seq-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;background:#fff;border-bottom:1px solid #e2e8f0}.qmx-seq-footer{border-top:1px solid #e2e8f0;border-bottom:0}.qmx-seq-title{font-size:18px;font-weight:850;color:#0f172a}.qmx-seq-subtitle{font-size:12px;color:#64748b}.qmx-seq-actions{display:flex;gap:7px;flex-wrap:wrap}.qmx-seq-btn,.qmx-seq-tool,.qmx-seq-preset{border:1px solid #cbd5e1;border-radius:9px;padding:9px 11px;background:#fff;color:#0f172a;font-weight:750;cursor:pointer;box-sizing:border-box;min-width:0;white-space:normal;overflow-wrap:anywhere;user-select:none}.qmx-seq-btn:hover,.qmx-seq-tool:hover,.qmx-seq-preset:hover{border-color:#2563eb}.qmx-seq-btn.primary{background:#2563eb;color:#fff;border-color:#2563eb}.qmx-seq-btn.danger{color:#dc2626}.qmx-seq-btn:disabled{opacity:.45;cursor:not-allowed}.qmx-seq-main{display:grid;grid-template-columns:260px minmax(0,1fr) 320px;gap:10px;padding:10px;min-height:0}.qmx-seq-panel{min-width:0;background:#fff;border:1px solid #e2e8f0;border-radius:11px;padding:10px;overflow-x:hidden;overflow-y:auto}.qmx-seq-tools,.qmx-seq-presets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:9px}.qmx-seq-tools>*,.qmx-seq-presets>*{min-width:0}.qmx-seq-tool small{display:block;color:#64748b}.qmx-seq-tool.active{border-color:#2563eb;background:#eff6ff;color:#1d4ed8}.qmx-seq-section{font-weight:800;margin-top:14px;padding-top:10px;border-top:1px solid #e2e8f0}.qmx-seq-canvas-wrap{min-width:0;min-height:0;background:#cbd5e1;border-radius:12px;padding:10px;overflow:auto;display:flex;align-items:center;justify-content:center}.qmx-seq-canvas{width:100%;min-width:620px}.qmx-seq-canvas svg{display:block;width:100%;height:auto;max-height:790px;background:#fff;box-shadow:0 8px 30px rgba(15,23,42,.16);touch-action:none}.qmx-seq-canvas [data-qmx-object]{cursor:move}.qmx-seq-field{margin:7px 0;min-width:0}.qmx-seq-field label{display:block;font-weight:700;font-size:12px;margin-bottom:4px}.qmx-seq-field input,.qmx-seq-field select,.qmx-seq-field textarea{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:8px;padding:8px;font:inherit}.qmx-seq-field textarea{min-height:76px;resize:vertical}.qmx-seq-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.qmx-seq-grid2>*{min-width:0}.qmx-seq-check{display:block;margin:8px 0}.qmx-seq-type,.qmx-seq-summary{margin-top:8px;padding:9px;border-radius:8px;background:#eff6ff;color:#1d4ed8;font-size:12px}.qmx-seq-empty{color:#64748b;text-align:center;padding:20px 4px}.qmx-seq-status{color:#64748b;min-height:18px}@media(max-width:1250px){.qmx-seq-main{grid-template-columns:230px minmax(500px,1fr) 290px}}@media(max-width:1050px){.qmx-seq-editor{padding:0}.qmx-seq-shell{width:100vw;height:100vh;border-radius:0}.qmx-seq-main{grid-template-columns:220px minmax(0,1fr)}.qmx-seq-main>.qmx-seq-panel:last-child{grid-column:1/-1;max-height:310px}}@media(max-width:720px){.qmx-seq-header,.qmx-seq-footer{align-items:flex-start;flex-direction:column}.qmx-seq-actions{width:100%}.qmx-seq-main{grid-template-columns:minmax(0,1fr);overflow:auto}.qmx-seq-main>.qmx-seq-panel:first-child{max-height:310px}.qmx-seq-main>.qmx-seq-panel:last-child{grid-column:auto;max-height:380px}.qmx-seq-canvas-wrap{min-height:430px}.qmx-seq-canvas{min-width:600px}}`;document.head.appendChild(style);}
    function buildEditor(){if(state.root)return;addStyles();const root=document.createElement('div');root.className='qmx-seq-editor';root.hidden=true;root.innerHTML=`<div class="qmx-seq-shell" role="dialog" aria-modal="true" aria-label="UML sequence diagram editor"><header class="qmx-seq-header"><div><div class="qmx-seq-title">UML Sequence / Interaction Diagram</div><div class="qmx-seq-subtitle">Lifelines, activations, smart messages, self-calls and combined fragments</div></div><div class="qmx-seq-actions"><button class="qmx-seq-btn" data-act="new">New</button><button class="qmx-seq-btn" data-act="undo">Undo</button><button class="qmx-seq-btn" data-act="redo">Redo</button><button class="qmx-seq-btn" data-act="duplicate">Duplicate</button><button class="qmx-seq-btn danger" data-act="delete">Delete</button><button class="qmx-seq-btn" data-act="close">×</button></div></header><main class="qmx-seq-main"><aside class="qmx-seq-panel"><strong>Sequence tools</strong><div class="qmx-seq-tools" data-tools></div><div class="qmx-seq-section">Interaction presets</div><div class="qmx-seq-presets"><button class="qmx-seq-preset" data-preset="login">Login flow</button><button class="qmx-seq-preset" data-preset="api">API request</button><button class="qmx-seq-preset" data-preset="checkout">Checkout</button><button class="qmx-seq-preset" data-preset="async">Async job</button><button class="qmx-seq-preset" data-preset="alt">alt fragment</button><button class="qmx-seq-preset" data-preset="observer">Observer</button><button class="qmx-seq-preset" data-preset="transaction">DB transaction</button><button class="qmx-seq-preset" data-preset="clear">Clear</button></div><p class="qmx-seq-subtitle">Choose Smart message, then click source and target lifelines. Messages remain attached when lifelines move.</p></aside><section class="qmx-seq-canvas-wrap"><div class="qmx-seq-canvas" data-canvas></div></section><aside class="qmx-seq-panel"><strong>Document</strong><div class="qmx-seq-field"><label>Title</label><input data-doc="title"></div><div class="qmx-seq-grid2"><div class="qmx-seq-field"><label>Width</label><input type="number" min="600" max="2400" data-doc="width"></div><div class="qmx-seq-field"><label>Height</label><input type="number" min="400" max="1800" data-doc="height"></div><div class="qmx-seq-field"><label>Grid size</label><input type="number" min="5" max="100" data-doc="gridSize"></div><div class="qmx-seq-field"><label>Background</label><input type="color" data-doc="background"></div></div><label class="qmx-seq-check"><input type="checkbox" data-doc="sequenceShowGrid"> Show grid</label><label class="qmx-seq-check"><input type="checkbox" data-doc="sequenceShowNumbers"> Show message numbers</label><label class="qmx-seq-check"><input type="checkbox" data-doc="sequenceShowActivations"> Show activations</label><label class="qmx-seq-check"><input type="checkbox" data-doc="sequenceShowFootbox"> Show foot boxes</label><label class="qmx-seq-check"><input type="checkbox" data-doc="snap"> Snap to grid</label><hr><strong>Selected object</strong><div data-selected></div><div class="qmx-seq-summary" data-summary></div></aside></main><footer class="qmx-seq-footer"><div class="qmx-seq-status" data-status></div><div class="qmx-seq-actions"><button class="qmx-seq-btn" data-act="export-svg">Export SVG</button><button class="qmx-seq-btn" data-act="export-png">Export PNG</button><button class="qmx-seq-btn primary" data-act="insert">Insert into question</button></div></footer></div>`;document.body.appendChild(root);state.root=root;state.canvas=root.querySelector('[data-canvas]');state.controls={tools:root.querySelector('[data-tools]'),selected:root.querySelector('[data-selected]'),summary:root.querySelector('[data-summary]'),status:root.querySelector('[data-status]'),undo:root.querySelector('[data-act="undo"]'),redo:root.querySelector('[data-act="redo"]')};TOOL_DEFS.forEach(([id,label,bn])=>{const button=document.createElement('button');button.className='qmx-seq-tool';button.dataset.tool=id;button.innerHTML=window.QmxDiagramToolButtonContent?window.QmxDiagramToolButtonContent(id,label,bn):`${esc(label)}<small>${esc(bn)}</small>`;state.controls.tools.appendChild(button);});root.addEventListener('click',onRootClick);root.addEventListener('change',onRootInput);root.addEventListener('input',onRootInput);state.canvas.addEventListener('pointerdown',onCanvasPointerDown);document.addEventListener('pointermove',onPointerMove);document.addEventListener('pointerup',onPointerUp);document.addEventListener('keydown',onKeydown);}
    function setStatus(message){if(state.controls.status)state.controls.status.textContent=message;}
    function open(context={}){buildEditor();state.context=context;state.document=context.initialSpec?Diagram.normalizeSpec(context.initialSpec):createDocument();if(state.document.mode!=='uml-sequence')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.connectionStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select');render();state.root.hidden=false;document.body.dataset.qmxSequenceOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(context.initialSpec?'Existing sequence diagram loaded.':'Choose a lifeline, message or interaction preset.');}
    function close(){if(!state.root||state.root.hidden)return;state.root.hidden=true;document.body.style.overflow=document.body.dataset.qmxSequenceOverflow||'';delete document.body.dataset.qmxSequenceOverflow;state.context?.textarea?.focus?.();}
    function findTokenTextarea(token){return Array.from(document.querySelectorAll('textarea')).find((textarea)=>textarea.value.includes(token))||null;}
    function openFromPreview(figure){const payload=String(figure?.dataset.qmxDiagramPayload||'');if(!payload)return false;let spec;try{spec=Diagram.decodePayload(payload);}catch(error){return false;}if(spec.mode!=='uml-sequence')return false;const token=`[[qmx-diagram:${payload}]]`;const textarea=findTokenTextarea(token)||window.QmxDiagramLauncher?.getActiveTextarea?.();let replaceRange=null;if(textarea){const start=textarea.value.indexOf(token);if(start>=0)replaceRange={start,end:start+token.length};}open({tool:{id:'uml-sequence'},textarea,initialSpec:spec,replaceRange,editMode:true});return true;}
    function registerHandlers(){const launcher=window.QmxDiagramLauncher;if(!launcher?.registerToolHandler)return false;let registered=false;['uml-sequence','sequence-diagram','interaction-diagram','uml-interaction'].forEach((id)=>{try{launcher.registerToolHandler(id,open);registered=true;}catch(error){}});return registered;}
    function onKeydown(event){if(!state.root||state.root.hidden)return;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(event.key==='Escape'&&['message','return-message','self-message'].includes(state.activeTool)){setTool('select');setStatus('Message creation cancelled.');event.preventDefault();return;}if(event.key==='Escape'){close();event.preventDefault();return;}if((event.key==='Delete'||event.key==='Backspace')&&!editing){event.preventDefault();deleteSelected();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'&&!editing){event.preventDefault();duplicateSelected();}}
    function init(){buildEditor();if(!registerHandlers())document.addEventListener('qmx:diagram-launcher-ready',registerHandlers,{once:true});}
    window.QmxUmlSequenceEditor=Object.freeze({version:'1.0.0',open,close,openFromPreview});
    document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init();
})(window, document);
